'use client';
import { useEffect, useRef, useState } from 'react';
import type { AssetPack } from '@/game/assets/asset-pack';
import type { Tank } from '@/game/core/types';
import type { StageRuntime } from '@/game/services/stage-runtime';
import { PAUSE, PauseMotion } from '@/game/core/pause-motion';
import { BubbleText, Dialog, Icon } from './ui';
import { TankInfoPanel } from './tank-info-panel';

const buttons = [
  {
    name: 'btnPlay_mc',
    label: 'PLAY',
    caption: 'Continue Playing',
    icon: 'play',
    action: 'resume',
  },
  { name: 'btn3_mc', label: 'Main menu', caption: 'Quit Playing', icon: 'quit', action: 'menu' },
  {
    name: 'btn5_mc',
    label: 'Tank info',
    caption: 'Tank Information',
    icon: 'info',
    action: 'info',
  },
  {
    name: 'btnSettings_mc',
    label: 'Settings',
    caption: 'Settings',
    icon: 'settings',
    action: 'settings',
  },
] as const;

/** One retained source button layer, shared alpha and stage clock for pause and Info. */
export function PausePanel({
  pack,
  tank,
  stage,
  fps,
  closeKey,
  onResume,
  onSettings,
  onMenu,
}: {
  pack: AssetPack;
  tank: Tank;
  stage: StageRuntime;
  fps: number;
  closeKey: string;
  onResume: () => void;
  onSettings: () => void;
  onMenu: () => void;
}) {
  const [motion] = useState(() => new PauseMotion());
  const [info, setInfo] = useState<'closed' | 'open' | 'closing'>('closed');
  const [closing, setClosing] = useState(false);
  const [caption, setCaption] = useState('');
  const [hovered, setHovered] = useState('');
  const nodes = useRef(new Map<string, HTMLElement>());
  const layer = useRef<HTMLDivElement>(null);
  const resumeRef = useRef(onResume);
  const infoSeen = useRef(false),
    resumeSent = useRef(false);
  useEffect(() => {
    resumeRef.current = onResume;
  }, [onResume]);
  useEffect(() => {
    if (info !== 'closed')
      (layer.current?.closest('[role="dialog"]') as HTMLElement | null)?.focus();
  }, [info]);
  useEffect(
    () =>
      stage.subscribe({
        beforeStep: () => motion.advance(),
        draw: () => {
          if (layer.current) {
            layer.current.style.opacity = String(motion.layerAlpha);
            layer.current.dataset.pauseAge = String(motion.age);
            layer.current.dataset.pausePhase = motion.phase;
          }
          for (const [name, node] of nodes.current) {
            const p = motion.positions[name],
              piece = PAUSE.pieces.find((piece) => piece.name === name)!;
            node.style.transform = `translate(${p.x}px,${p.y}px) scale(${motion.scales[name]}) translate(${piece.bounds.x}px,${piece.bounds.y}px)`;
            node.style.opacity = String(
              name === 'btnPlay_mc'
                ? motion.playAlpha
                : name === 'Paused_mc'
                  ? motion.titleAlpha
                  : 1,
            );
          }
          if (motion.finished && !resumeSent.current) {
            resumeSent.current = true;
            resumeRef.current();
          }
        },
      }),
    [motion, stage],
  );
  const close = () => {
    if (closing) return;
    if (info === 'open') {
      motion.phase = 'menu';
      setInfo('closing');
    } else {
      motion.phase = 'closing';
      setClosing(true);
    }
  };
  const resume = () => {
    motion.phase = 'closing';
    setClosing(true);
  };
  const hover = (name = '', text = '') => {
    motion.hovered = name;
    setHovered(name);
    setCaption(text);
  };
  const title = PAUSE.pieces.find((piece) => piece.name === 'Paused_mc')!;
  const titleRaster = pack.uiFrames.get(title.symbol)?.[0];
  const pieceStyle = (piece: typeof title) => {
    const p = motion.positions[piece.name];
    return {
      left: 0,
      top: 0,
      width: piece.bounds.width,
      height: piece.bounds.height,
      transformOrigin: '0 0',
      transform: `translate(${p.x}px,${p.y}px) scale(${motion.scales[piece.name]}) translate(${piece.bounds.x}px,${piece.bounds.y}px)`,
    };
  };
  return (
    <Dialog
      title={info === 'open' ? 'Tank information' : 'Paused'}
      className="stage-dialog pause-screen"
      closeKey={closeKey}
      onClose={close}
      onShortcutClose={resume}
    >
      <div
        ref={layer}
        className="pause-button-layer"
        inert={closing}
        style={{ opacity: motion.layerAlpha }}
        data-pause-age={motion.age}
        data-pause-phase={motion.phase}
      >
        <div inert={info === 'open' || closing} aria-hidden={info === 'open' || closing}>
          <div
            className="pause-title"
            ref={(node) => {
              if (node) nodes.current.set(title.name, node);
              else nodes.current.delete(title.name);
            }}
            style={pieceStyle(title)}
          >
            {titleRaster ? (
              <img
                alt="paused"
                src={titleRaster.url}
                style={{
                  position: 'absolute',
                  left: titleRaster.x - title.bounds.x,
                  top: titleRaster.y - title.bounds.y,
                  width: titleRaster.width,
                  height: titleRaster.height,
                }}
              />
            ) : (
              <BubbleText pack={pack} size={40}>
                paused
              </BubbleText>
            )}
          </div>
          {buttons.map((button) => {
            const piece = PAUSE.pieces.find((piece) => piece.name === button.name)!;
            const raster = pack.uiFrames.get(piece.symbol)?.[hovered === button.name ? 1 : 0];
            return (
              <button
                key={button.name}
                className="pause-orb"
                aria-label={button.label}
                data-pause-piece={button.name}
                style={pieceStyle(piece)}
                ref={(node) => {
                  if (node) nodes.current.set(button.name, node);
                  else nodes.current.delete(button.name);
                }}
                onPointerEnter={() => hover(button.name, button.caption)}
                onPointerLeave={() => hover()}
                onFocus={() => hover(button.name, button.caption)}
                onBlur={() => hover()}
                onClick={() => {
                  hover();
                  if (button.action === 'resume') close();
                  else if (button.action === 'info') {
                    infoSeen.current = true;
                    motion.phase = 'info';
                    setInfo('open');
                  } else if (button.action === 'settings') onSettings();
                  else onMenu();
                }}
              >
                {raster ? (
                  <img
                    src={raster.url}
                    alt=""
                    style={{
                      position: 'absolute',
                      left: raster.x - piece.bounds.x,
                      top: raster.y - piece.bounds.y,
                      width: raster.width,
                      height: raster.height,
                    }}
                  />
                ) : (
                  <Icon name={button.icon} size={20} />
                )}
              </button>
            );
          })}
          <div className="pause-caption" aria-live="polite">
            <BubbleText pack={pack} font="Accidental Presidency" size={17}>
              {caption || ' '}
            </BubbleText>
          </div>
        </div>
        <TankInfoPanel
          pack={pack}
          tank={tank}
          fps={fps}
          stage={stage}
          embedded
          frozen={closing || !infoSeen.current}
          phase={info}
          onExitStart={() => {
            motion.phase = 'menu';
            setInfo('closing');
          }}
          onClose={() => {
            if (info === 'closing') setInfo('closed');
          }}
        />
      </div>
    </Dialog>
  );
}

import { CLASS_ARMOR, CLASS_SPEED } from './constants';
import type { TankDesign } from './types';
import { partById } from '../data/catalog';
import { HUD } from './hud';
import { displayPixel } from './display-values';

export const TANK_INFO = HUD.tankInfo;

/** PauseMenu._-Bz: sort IDs, then abbreviate each category independently. */
export function infoWeapons(tank: TankDesign, category: 2 | 3 | 5) {
  const counts = new Map<number, number>();
  for (const part of tank.parts)
    if (Math.floor(part.type / 1000) === category)
      counts.set(part.type, (counts.get(part.type) ?? 0) + 1);
  return (
    [...counts]
      .sort(([a], [b]) => a - b)
      .map(([id, count]) => {
        const part = partById(id);
        if (!part) return String(id);
        if (counts.size > 2)
          return count === 1 ? `1 ${part.shortName.slice(0, -2)}` : `${count} ${part.shortName}`;
        return count === 1 ? part.name : `${count} ${part.pluralName}`;
      })
      .join(', ') || 'N/A'
  );
}

export function tankInfoFields(tank: TankDesign): Record<string, string> {
  const index = tank.classId - 1;
  return {
    txtClass_txt: String(tank.classId),
    txtSpeed_txt: String(CLASS_SPEED[index]),
    txtArmor_txt: `${Math.round(CLASS_ARMOR[index] * 100)}%`,
    txtPrimaryWeapons_txt: infoWeapons(tank, 2),
    txtSecondaryWeapons_txt: infoWeapons(tank, 3),
    txtPassiveWeapons_txt: infoWeapons(tank, 5),
  };
}

/** Authored 50fps-frame easing, with the original sequential entrance gates. */
export class TankInfoMotion {
  positions = Object.fromEntries(TANK_INFO.pieces.map((p) => [p.name, { x: p.x, y: p.y }]));
  exiting = false;
  constructor() {
    const p = this.positions,
      out = TANK_INFO.out;
    p.Title_mc.y = p.ClassHealth_mc.y = out.ButtonTopOut_mc.y;
    for (const name of [
      'PrimaryWeapons_mc',
      'SecondaryWeapons_mc',
      'PassiveWeapons_mc',
      'btnBack_mc',
    ])
      p[name].x = out.ButtonLeftOut_mc.x;
    p.TankImage_mc.x = out.ButtonTankOut_mc.x;
  }
  private approach(name: string, axis: 'x' | 'y', target?: number, rate = 0.1) {
    const pos = this.positions[name];
    pos[axis] = displayPixel(
      pos[axis] * (1 - rate) +
        (target ?? TANK_INFO.pieces.find((p) => p.name === name)![axis]) * rate,
    );
  }
  advance() {
    const p = this.positions,
      out = TANK_INFO.out;
    if (this.exiting) {
      for (const name of ['Title_mc', 'ClassHealth_mc'])
        this.approach(name, 'y', out.ButtonTopOut_mc.y, 0.07);
      this.approach('TankImage_mc', 'x', out.ButtonTankOut_mc.x, 0.07);
      for (const name of [
        'PrimaryWeapons_mc',
        'SecondaryWeapons_mc',
        'PassiveWeapons_mc',
        'btnBack_mc',
      ])
        this.approach(name, 'x', out.ButtonLeftOut_mc.x, 0.07);
      return;
    }
    this.approach('Title_mc', 'y');
    if (p.Title_mc.y > 10) this.approach('ClassHealth_mc', 'y');
    if (p.ClassHealth_mc.y > 10) this.approach('TankImage_mc', 'x');
    if (p.TankImage_mc.x < 500) this.approach('PrimaryWeapons_mc', 'x');
    if (p.PrimaryWeapons_mc.x > 30) this.approach('SecondaryWeapons_mc', 'x');
    if (p.SecondaryWeapons_mc.x > 30) this.approach('PassiveWeapons_mc', 'x');
    if (p.PassiveWeapons_mc.x > 30) this.approach('btnBack_mc', 'x');
  }
  get finished() {
    return (
      this.exiting &&
      TANK_INFO.pieces.every((piece) => {
        if (piece.name === 'TankImage_mc') return true; // Avatar returns to the world immediately.
        const p = this.positions[piece.name],
          b = piece.bounds;
        return (
          p.x + b.x + b.width <= 0 ||
          p.y + b.y + b.height <= 0 ||
          p.x + b.x >= 550 ||
          p.y + b.y >= 450
        );
      })
    );
  }
}

/** Flash wraps at spaces; an unbroken name may also exceed a line's width. */
export function infoTextLines(text: string, width: number, measure: (text: string) => number) {
  const lines: string[] = [];
  let line = '';
  for (const word of text.split(' ')) {
    const next = line ? `${line} ${word}` : word;
    if (line && measure(next) > width) {
      lines.push(line);
      line = word;
    } else line = next;
  }
  if (line) lines.push(line);
  return lines;
}
